import java.util.*;

class Solution {
    public boolean searchBST(TreeNode root, int target) {
        while (root != null) {
            if (root.val == target) {
                return true;
            }
            if (target < root.val) {
                root = root.right;
            } else {
                root = root.left;
            }
        }
        return false;
    }
}
